// Rose's device key (browser only): generated by WebCrypto as non-extractable and kept in IndexedDB,
// so the private half never leaves this browser and can't be read even by this page's own code.

import type { CryptoKey } from "jose";

const DB = "secondkey-device";
const STORE = "keys";
const ID = "rose";

function idb<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open(DB, 1);
    open.onupgradeneeded = () => open.result.createObjectStore(STORE);
    open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const tx = open.result.transaction(STORE, mode);
      const req = fn(tx.objectStore(STORE));
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    };
  });
}

export interface DeviceKey {
  privateKey: CryptoKey;
  publicJwk: { kty: string; crv: string; x: string; y: string };
  /** False when the browser wouldn't store it (private window): the key lasts for this page only. */
  persisted: boolean;
}

let memory: DeviceKey | undefined;

/** Rose's device key: loaded from IndexedDB, or generated (non-extractable) and stored. */
export async function deviceKey(): Promise<DeviceKey> {
  if (memory) return memory;
  try {
    const stored = await idb<{ privateKey: CryptoKey; publicJwk: DeviceKey["publicJwk"] } | undefined>("readonly", (s) => s.get(ID));
    if (stored?.privateKey) return (memory = { ...stored, persisted: true });
  } catch {
    /* no IndexedDB: fall through to a page-lifetime key */
  }
  const pair = (await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])) as { privateKey: CryptoKey; publicKey: CryptoKey };
  const jwk = await crypto.subtle.exportKey("jwk", pair.publicKey);
  const publicJwk = { kty: jwk.kty!, crv: jwk.crv!, x: jwk.x!, y: jwk.y! };
  let persisted = false;
  try {
    await idb("readwrite", (s) => s.put({ privateKey: pair.privateKey, publicJwk }, ID));
    persisted = true;
  } catch {
    persisted = false;
  }
  return (memory = { privateKey: pair.privateKey, publicJwk, persisted });
}
